  a1.Recipe e => {'collection': 'Recipe', 'id': e.id},
  a1.JournalItem e => {'collection': 'JournalItem', 'id': e.id},
  a1.DocItem e => {'collection': 'DocItem', 'id': e.path},
  _ => null,
};

